import sympy as sp
a=sp.symbols('a',positive=True)
sols=sp.solve(a**6-2*a**3+1,a)
vals={sp.simplify(s+1/s) for s in sols}
assert vals=={2}
v=vals.pop()
opts={'A':2,'B':4,'C':1,'D':3}
assert v==opts['A']
for k in 'BCD': assert v!=opts[k]

def ok(s):
    a,b,c=sorted([6,12,s]); return a+b>c and len({6,12,s})<=2
opts={'A':8,'B':12,'C':14,'D':6}
fits=[k for k,v in opts.items() if ok(v)]
assert fits==['B']
